<?php require_once __DIR__.'/../lib/bootstrap.php'; requestMethod('POST'); requireCsrf(); $d=requestJson(8000); $email=strtolower(trim((string)($d['email']??''))); $password=(string)($d['password']??''); if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$password==='') apiRespond(['error'=>'Introduce un correo válido y tu contraseña.'],422); $u=db()->findUserByEmail($email); if(!$u||!password_verify($password,(string)$u['password'])) apiRespond(['error'=>'El correo o la contraseña no son correctos.'],401); session_regenerate_id(true); $_SESSION['user_id']=(int)$u['id']; $_SESSION['role']=$u['rol']; $_SESSION['csrf_token']=bin2hex(random_bytes(32)); $newToken=(string)$_SESSION['csrf_token']; db()->addEvent('user.logged_in',(int)$u['id'],null,null,['role'=>$u['rol']]); apiRespond(['ok'=>true,'csrfToken'=>$newToken,'user'=>['id'=>(int)$u['id'],'firstName'=>$u['nombre'],'lastName'=>$u['apellidos']??'','email'=>$u['email'],'role'=>$u['rol']]]);
